		public static void Seed() {
			using (var db = new cspEntities()) {

				var sb = new StringBuilder();
				foreach (var pst in PartSubTypesAll) {
					sb.Append(string.Format("INSERT INTO partsubtype(PartSubtypeId, PartTypeId, Name, PanDbIdentification, LicenseFeaturesName, LicenseType, IsActive) VALUES({0}, {1}, '{2}', '{3}', '{4}', {5}, {6});", pst.PartSubtypeId, pst.PartTypeId, pst.Name, pst.PanDbIdentification, pst.LicenseFeaturesName, pst.LicenseType, (pst.IsActive ?? true) ? 1 : 0));
				}

				db.Database.ExecuteSqlCommand(sb.ToString());
			}
		}
